/*
 * Embed the LVGL binary UI fonts (generated by lv_font_conv, committed under
 * openrtx/fonts/) directly into flash via .incbin, one blob per fontSize_t.
 * The paths resolve relative to the build directory (a sibling of the repo
 * root, matching voicePromptData.S). Colour displays get the 4bpp anti-aliased
 * set (plus the 1bpp text set as _font_mono_* for the run-time-selectable crisp
 * font), monochrome targets the compact 1bpp set, chosen by the CONFIG_FONT_AA
 * define that meson sets for RGB565 targets (hwconfig.h can't be included here —
 * it contains C — so the pixel format is passed in as a -D flag instead).
 */

.section .note.GNU-stack,""
.section .rodata

.macro FONT_BLOB name, path
.global _font_\name\()_start
.global _font_\name\()_end
_font_\name\()_start:
    .incbin "\path"
.set _font_\name\()_end, .
.endm

/* Custom icon font: per-size blobs holding app-specific glyphs (today just the
 * M17 logo, U+E900), layered onto the base text font as a fallback so they draw
 * without touching the ubuntu blobs. Kept separate from the FontAwesome subset
 * that is merged into the text font. Same 1bpp/4bpp split as above. */
.macro ICON_BLOB name, path
.global _icons_\name\()_start
.global _icons_\name\()_end
_icons_\name\()_start:
    .incbin "\path"
.set _icons_\name\()_end, .
.endm

#ifdef CONFIG_FONT_AA
FONT_BLOB 5,  "../openrtx/fonts/ubuntu_5_4.bin"
FONT_BLOB 6,  "../openrtx/fonts/ubuntu_6_4.bin"
FONT_BLOB 8,  "../openrtx/fonts/ubuntu_8_4.bin"
FONT_BLOB 9,  "../openrtx/fonts/ubuntu_9_4.bin"
FONT_BLOB 10, "../openrtx/fonts/ubuntu_10_4.bin"
FONT_BLOB 12, "../openrtx/fonts/ubuntu_12_4.bin"
FONT_BLOB 16, "../openrtx/fonts/ubuntu_16_4.bin"

ICON_BLOB 5,  "../openrtx/fonts/icons_5_4.bin"
ICON_BLOB 6,  "../openrtx/fonts/icons_6_4.bin"
ICON_BLOB 8,  "../openrtx/fonts/icons_8_4.bin"
ICON_BLOB 9,  "../openrtx/fonts/icons_9_4.bin"
ICON_BLOB 10, "../openrtx/fonts/icons_10_4.bin"
ICON_BLOB 12, "../openrtx/fonts/icons_12_4.bin"
ICON_BLOB 16, "../openrtx/fonts/icons_16_4.bin"

/* Colour targets also embed the compact 1bpp text set as _font_mono_*, so the
 * user can switch to a crisp (non-anti-aliased) font at run time. Text only —
 * the M17 icon glyph keeps its 4bpp blob. ~19 KB of extra flash. */
FONT_BLOB mono_5,  "../openrtx/fonts/ubuntu_5_1.bin"
FONT_BLOB mono_6,  "../openrtx/fonts/ubuntu_6_1.bin"
FONT_BLOB mono_8,  "../openrtx/fonts/ubuntu_8_1.bin"
FONT_BLOB mono_9,  "../openrtx/fonts/ubuntu_9_1.bin"
FONT_BLOB mono_10, "../openrtx/fonts/ubuntu_10_1.bin"
FONT_BLOB mono_12, "../openrtx/fonts/ubuntu_12_1.bin"
FONT_BLOB mono_16, "../openrtx/fonts/ubuntu_16_1.bin"
#else
FONT_BLOB 5,  "../openrtx/fonts/ubuntu_5_1.bin"
FONT_BLOB 6,  "../openrtx/fonts/ubuntu_6_1.bin"
FONT_BLOB 8,  "../openrtx/fonts/ubuntu_8_1.bin"
FONT_BLOB 9,  "../openrtx/fonts/ubuntu_9_1.bin"
FONT_BLOB 10, "../openrtx/fonts/ubuntu_10_1.bin"
FONT_BLOB 12, "../openrtx/fonts/ubuntu_12_1.bin"
FONT_BLOB 16, "../openrtx/fonts/ubuntu_16_1.bin"

ICON_BLOB 5,  "../openrtx/fonts/icons_5_1.bin"
ICON_BLOB 6,  "../openrtx/fonts/icons_6_1.bin"
ICON_BLOB 8,  "../openrtx/fonts/icons_8_1.bin"
ICON_BLOB 9,  "../openrtx/fonts/icons_9_1.bin"
ICON_BLOB 10, "../openrtx/fonts/icons_10_1.bin"
ICON_BLOB 12, "../openrtx/fonts/icons_12_1.bin"
ICON_BLOB 16, "../openrtx/fonts/icons_16_1.bin"
#endif
